CREATE FUNCTION public.can_manage_account_connections(_ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) $$;
REVOKE ALL ON FUNCTION public.can_manage_account_connections(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_manage_account_connections(uuid) TO authenticated,service_role;
CREATE TABLE public.account_relationship_preferences(workspace_id uuid PRIMARY KEY REFERENCES public.workspaces(id),referral_workspace_id uuid REFERENCES public.workspaces(id),referral_name text,preferred_provider_id uuid REFERENCES public.workspaces(id),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,person_mfn_id text,workspace_mfn_id text,source text NOT NULL DEFAULT 'settings');
GRANT SELECT ON public.account_relationship_preferences TO authenticated; GRANT ALL ON public.account_relationship_preferences TO service_role;
ALTER TABLE public.account_relationship_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY relationship_preferences_read ON public.account_relationship_preferences FOR SELECT TO authenticated USING(public.can_manage_account_connections(workspace_id));
CREATE TABLE public.account_connection_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mfn_id text NOT NULL UNIQUE DEFAULT ('MFN-I-'||upper(replace(gen_random_uuid()::text,'-',''))),inviter_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),recipient_workspace_id uuid REFERENCES public.workspaces(id),recipient_email text NOT NULL,intended_type text NOT NULL CHECK(intended_type IN ('provider','facility')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','canceled','expired')),token_hash text NOT NULL CHECK(length(token_hash)=64),expires_at timestamptz NOT NULL,created_by uuid NOT NULL,person_mfn_id text NOT NULL,workspace_mfn_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),generation integer NOT NULL DEFAULT 1,delivery_status text NOT NULL DEFAULT 'not_sent',CHECK(inviter_workspace_id IS DISTINCT FROM recipient_workspace_id));
GRANT SELECT(id,mfn_id,inviter_workspace_id,recipient_workspace_id,intended_type,status,expires_at,created_by,person_mfn_id,workspace_mfn_id,created_at,updated_at,generation,delivery_status) ON public.account_connection_invitations TO authenticated; GRANT ALL ON public.account_connection_invitations TO service_role;
ALTER TABLE public.account_connection_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitation_scoped_read ON public.account_connection_invitations FOR SELECT TO authenticated USING(public.can_manage_account_connections(inviter_workspace_id) OR public.can_manage_account_connections(recipient_workspace_id));
CREATE TABLE public.account_business_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_a uuid NOT NULL REFERENCES public.workspaces(id),workspace_b uuid NOT NULL REFERENCES public.workspaces(id),invitation_id uuid NOT NULL REFERENCES public.account_connection_invitations(id),active boolean NOT NULL DEFAULT true,accepted_by uuid NOT NULL,person_mfn_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_a,workspace_b),CHECK(workspace_a<workspace_b));
GRANT SELECT ON public.account_business_connections TO authenticated; GRANT ALL ON public.account_business_connections TO service_role;
ALTER TABLE public.account_business_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_connection_read ON public.account_business_connections FOR SELECT TO authenticated USING(public.can_manage_account_connections(workspace_a) OR public.can_manage_account_connections(workspace_b));
CREATE TABLE public.account_relationship_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),record_id uuid,action text NOT NULL,actor_id uuid NOT NULL,person_mfn_id text NOT NULL,workspace_mfn_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.account_relationship_events TO authenticated; GRANT ALL ON public.account_relationship_events TO service_role;
ALTER TABLE public.account_relationship_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY relationship_event_read ON public.account_relationship_events FOR SELECT TO authenticated USING(public.can_manage_account_connections(workspace_id));
CREATE FUNCTION public.relationship_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Relationship audit is append-only'; END $$;
CREATE TRIGGER relationship_events_immutable BEFORE UPDATE OR DELETE ON public.account_relationship_events FOR EACH ROW EXECUTE FUNCTION public.relationship_history_immutable();
CREATE FUNCTION public.search_connection_businesses(_ws uuid,_mode text,_value text) RETURNS TABLE(workspace_id uuid,business_name text,mfn_id text,business_type text,location text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR length(_value)<2 OR length(_value)>254 OR _mode NOT IN ('name','email','phone') THEN RAISE EXCEPTION 'Business search unavailable'; END IF;
 RETURN QUERY SELECT p.workspace_id,p.business_name,p.mfn_id,'provider'::text,array_to_string(p.cities,', ') FROM public.list_network_providers() p WHERE p.workspace_id<>_ws AND ((_mode='name' AND p.business_name ILIKE '%'||_value||'%') OR (_mode='email' AND lower(trim(p.business_contact_email))=lower(trim(_value))) OR (_mode='phone' AND length(regexp_replace(_value,'[^0-9]','','g'))>=10 AND regexp_replace(p.business_contact_phone,'[^0-9]','','g')=regexp_replace(_value,'[^0-9]','','g'))) ORDER BY p.business_name LIMIT 20;
 END $$;
REVOKE ALL ON FUNCTION public.search_connection_businesses(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.search_connection_businesses(uuid,text,text) TO authenticated;
CREATE FUNCTION public.save_account_relationship_preferences(_ws uuid,_kind text,_target uuid,_name text,_confirmed boolean,_source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _person text;_account text;_old jsonb; BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true OR _kind NOT IN ('referral','preferred') OR _source NOT IN ('onboarding','settings') OR length(coalesce(_name,''))>200 OR (SELECT account_type FROM public.workspaces WHERE id=_ws)='provider' THEN RAISE EXCEPTION 'Relationship update unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 IF _target IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.list_network_providers() p WHERE p.workspace_id=_target) THEN RAISE EXCEPTION 'Public business unavailable'; END IF;
 SELECT mfn_id INTO _person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO _account FROM public.workspaces WHERE id=_ws;
 SELECT to_jsonb(r) INTO _old FROM public.account_relationship_preferences r WHERE workspace_id=_ws;
 INSERT INTO public.account_relationship_preferences(workspace_id,updated_by,person_mfn_id,workspace_mfn_id,source) VALUES(_ws,auth.uid(),_person,_account,_source) ON CONFLICT DO NOTHING;
 IF _kind='referral' THEN UPDATE public.account_relationship_preferences SET referral_workspace_id=_target,referral_name=nullif(trim(_name),''),updated_by=auth.uid(),person_mfn_id=_person,workspace_mfn_id=_account,source=_source,updated_at=now() WHERE workspace_id=_ws;
 ELSE UPDATE public.account_relationship_preferences SET preferred_provider_id=_target,updated_by=auth.uid(),person_mfn_id=_person,workspace_mfn_id=_account,source=_source,updated_at=now() WHERE workspace_id=_ws; END IF;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,_kind||'_confirmed',auth.uid(),_person,_account,jsonb_build_object('previous',_old,'target',_target,'name',nullif(trim(_name),''),'source',_source)); END $$;
REVOKE ALL ON FUNCTION public.save_account_relationship_preferences(uuid,text,uuid,text,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_account_relationship_preferences(uuid,text,uuid,text,boolean,text) TO authenticated;
CREATE FUNCTION public.manage_account_invitation(_ws uuid,_action text,_id uuid,_email text,_type text,_hash text,_confirmed boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _i public.account_connection_invitations;_person text;_account text;_idout uuid; BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true OR _action NOT IN ('send','resend','cancel','accept','decline') THEN RAISE EXCEPTION 'Invitation unavailable'; END IF;
 SELECT mfn_id INTO _person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO _account FROM public.workspaces WHERE id=_ws;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 IF _action='send' THEN
 IF _type NOT IN ('provider','facility') OR length(_email)>254 OR _email !~ '^[^ @]+@[^ @]+\.[^ @]+$' OR _hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid invitation'; END IF;
 IF (SELECT count(*) FROM public.account_connection_invitations WHERE inviter_workspace_id=_ws AND created_at>now()-interval '1 hour')>=10 THEN RAISE EXCEPTION 'Please wait before inviting more businesses'; END IF;
 INSERT INTO public.account_connection_invitations(inviter_workspace_id,recipient_email,intended_type,token_hash,expires_at,created_by,person_mfn_id,workspace_mfn_id) VALUES(_ws,lower(trim(_email)),_type,_hash,now()+interval '7 days',auth.uid(),_person,_account) RETURNING id INTO _idout;
 ELSE
 SELECT * INTO _i FROM public.account_connection_invitations WHERE id=_id FOR UPDATE;
 IF NOT FOUND OR _i.status<>'pending' THEN RAISE EXCEPTION 'Invitation unavailable'; END IF;
 _idout:=_i.id;
 IF _action IN ('resend','cancel') THEN
 IF _i.inviter_workspace_id<>_ws THEN RAISE EXCEPTION 'Invitation unavailable'; END IF;
 IF _action='cancel' THEN UPDATE public.account_connection_invitations SET status='canceled',token_hash=repeat('0',64),updated_at=now() WHERE id=_id;
 ELSE IF _i.updated_at>now()-interval '1 minute' OR _hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Wait before resending'; END IF; UPDATE public.account_connection_invitations SET token_hash=_hash,expires_at=now()+interval '7 days',generation=generation+1,delivery_status='not_sent',updated_at=now() WHERE id=_id; END IF;
 ELSE
 IF _i.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired'; END IF;
 IF lower(coalesce(auth.jwt()->>'email',''))<>_i.recipient_email OR _i.inviter_workspace_id=_ws OR NOT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=_ws AND ((_i.intended_type='provider' AND w.account_type='provider') OR (_i.intended_type='facility' AND w.account_type IN ('facility','hospital')))) THEN RAISE EXCEPTION 'Sign in with the invited email and correct business account'; END IF;
 IF _hash IS NOT NULL AND _hash<>_i.token_hash THEN RAISE EXCEPTION 'Invitation link unavailable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_i.inviter_workspace_id AND status='active' AND NOT is_test_account) THEN RAISE EXCEPTION 'Inviting account unavailable'; END IF;
 UPDATE public.account_connection_invitations SET status=CASE WHEN _action='accept' THEN 'accepted' ELSE 'declined' END,recipient_workspace_id=_ws,token_hash=repeat('0',64),updated_at=now() WHERE id=_id;
 IF _action='accept' THEN INSERT INTO public.account_business_connections(workspace_a,workspace_b,invitation_id,accepted_by,person_mfn_id) VALUES(least(_ws,_i.inviter_workspace_id),greatest(_ws,_i.inviter_workspace_id),_id,auth.uid(),_person) ON CONFLICT(workspace_a,workspace_b) DO UPDATE SET active=true,invitation_id=_id,accepted_by=auth.uid(),person_mfn_id=_person,updated_at=now(); END IF;
 END IF; END IF;
 INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,person_mfn_id,workspace_mfn_id) VALUES(_ws,_idout,'invitation_'||_action,auth.uid(),_person,_account);
 RETURN _idout; END $$;
REVOKE ALL ON FUNCTION public.manage_account_invitation(uuid,text,uuid,text,text,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_account_invitation(uuid,text,uuid,text,text,text,boolean) TO authenticated;
CREATE FUNCTION public.deactivate_account_connection(_ws uuid,_id uuid,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _person text;_account text; BEGIN IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Connection unavailable'; END IF; UPDATE public.account_business_connections SET active=false,updated_at=now() WHERE id=_id AND _ws IN (workspace_a,workspace_b) AND active=true; IF NOT FOUND THEN RAISE EXCEPTION 'Connection unavailable'; END IF; SELECT mfn_id INTO _person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO _account FROM public.workspaces WHERE id=_ws; INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,person_mfn_id,workspace_mfn_id) VALUES(_ws,_id,'connection_deactivated',auth.uid(),_person,_account); END $$;
REVOKE ALL ON FUNCTION public.deactivate_account_connection(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.deactivate_account_connection(uuid,uuid,boolean) TO authenticated;
COMMENT ON TABLE public.account_relationship_preferences IS 'Source attribution and preferred provider only; never grants record, medical, messaging, membership or financial permissions.';
COMMENT ON TABLE public.account_business_connections IS 'Explicitly accepted connections; existing messaging authorization still required. No workspace membership or trip/payment access.';